use v5.42;
use strict;
use warnings;
use JSON::PP ();
use Digest::SHA 'sha256_hex';
use File::Basename 'dirname';
use File::Temp 'tempfile';
use Cwd 'abs_path';
use Time::HiRes qw(clock_gettime CLOCK_MONOTONIC);
use IPC::Open3 'open3';
use lib 'bench/lib';
use Wump::BenchMatrix 'validate_result';
@ARGV == 4 or die "usage: capture-calls.pl BEFORE AFTER STOCK METADATA\n";
my ($before, $after, $stock, $metadata) = @ARGV;
sub contents ($path) {
	open my $in, '<', $path or die "$path: $!";
	my $text = do {local $/; <$in>};
	close $in or die $!;
	return $text;
}
sub capture (@command) {
	my ($errors) = tempfile(UNLINK => 1);
	my ($input, $output);
	my $pid = open3($input, $output, '>&' . fileno($errors), @command);
	close $input or die $!;
	my $text = do {local $/; <$output>};
	close $output or die $!;
	waitpid($pid, 0) == $pid or die $!;
	my $status = $?;
	seek $errors, 0, 0 or die $!;
	my $diagnostics = do {local $/; <$errors>};
	!$status && !length($diagnostics) or die "failed ($status): @command\n$diagnostics";
	return $text;
}
for my $key (qw(PERL5OPT PERL5LIB PERLLIB PERL_UNICODE PERL_HASH_SEED PERL_PERTURB_KEYS PERLIO PERL_DESTRUCT_LEVEL)) {delete $ENV{$key}}
local $ENV{LC_ALL} = 'C'; local $ENV{LANG} = 'C'; local $ENV{TZ} = 'UTC';
capture('git', 'status', '--porcelain') eq '' or die "dirty source";
my $revision = capture('git', 'rev-parse', 'HEAD'); chomp $revision;
my @sources = qw(bench/matrix-worker.pl bench/lib/Wump/BenchMatrix.pm perl/lib/Wump.pm perl/parallel.pl perl/core/wump_memory.c);
my %hashes = map {$_ => sha256_hex(contents($_))} ($before, $after, $stock, @sources);
my %binaries;
for my $pair ([before => $before], [after => $after], [stock => $stock]) {
	my ($role, $path) = @$pair;
	my $config = capture($path, '-I'.dirname($path).'/lib', '-MConfig', '-MJSON::PP', '-e',
		q{print JSON::PP::encode_json({map {$_ => $Config::Config{$_} // ''} qw(version archname cc gccversion ccflags ldflags lddlflags optimize usemultiplicity useithreads use64bitall)})});
	$binaries{$role} = {path => abs_path($path), sha256 => $hashes{$path}, config => JSON::PP::decode_json($config)};
}
JSON::PP->new->canonical->encode($binaries{before}{config}) eq JSON::PP->new->canonical->encode($binaries{after}{config}) or die 'config mismatch';
my $cpu = contents('/proc/cpuinfo'); $cpu =~ /^model name\s*:\s*(.+)$/m or die 'CPU';
my $cpu_model = $1;
my $kernel = capture('uname', '-srmo'); chomp $kernel;
my $sequence = 0;
for my $run (1..7) {
	my @sizes = $run % 2 ? (50000, 2000000) : (2000000, 50000);
	for my $n (@sizes) {
		for my $role ($run % 2 ? ('before', 'after') : ('after', 'before')) {
			local $ENV{WUMP_MATRIX_MODE} = 'wump';
			local $ENV{WUMPPROCS} = 2;
			local $ENV{WUMP_MATRIX_SLOTS} = 2;
			my $binary = $binaries{$role}{path};
			my $start = clock_gettime(CLOCK_MONOTONIC);
			my $text = capture('taskset', '-c', '0,2,4,6', 'timeout', '90s', $binary,
				'-I'.dirname($binary).'/lib', '-Iperl/lib', 'bench/matrix-worker.pl', 'yield', $n, 8);
			my $elapsed = clock_gettime(CLOCK_MONOTONIC) - $start;
			my $value = JSON::PP::decode_json($text);
			validate_result($value, 'yield', 'wump-2', $n, 8);
			$value->{status} eq 'ok' && $value->{wall_seconds} <= $elapsed or die 'invalid timing';
			print JSON::PP->new->canonical->encode({%$value, role => $role, run => $run,
				sequence => ++$sequence, process_seconds => $elapsed}), "\n";
		}
	}
}
$sequence == 28 or die 'incomplete capture';
for my $path (keys %hashes) {sha256_hex(contents($path)) eq $hashes{$path} or die "changed $path"}
capture('git', 'status', '--porcelain') eq '' or die 'source changed';
open my $out, '>', "$metadata.tmp" or die $!;
print {$out} JSON::PP->new->canonical->pretty->encode({source_revision => $revision,
	source_dirty => JSON::PP::false, binaries => \%binaries, sha256 => \%hashes,
	cpu_model => $cpu_model, kernel => $kernel, affinity => '0,2,4,6',
	runs => 7, iterations => [50000,2000000], jobs => 8, slots => 2, samples => $sequence,
	runner_source => contents(__FILE__)}) or die $!;
close $out or die $!;
rename "$metadata.tmp", $metadata or die $!;
